<script setup>
import NavigationIcon from '@/Components/NavigationIcon.vue';import{Link,usePage}from'@inertiajs/vue3';import{computed}from'vue';const permissions=computed(()=>usePage().props.auth.permissions||[]);const can=value=>permissions.value.includes(value);const groups=computed(()=>[{label:'Workspace',links:[['overview','staff.dashboard','Overview','staff.dashboard',true]]},{label:'Sales & customers',links:[['leads','admin.leads.index','CRM Pipeline','admin.leads.*',can('lead.view')],['customers','admin.customers.index','Customers','admin.customers.*',can('customer.view')],['quotations','admin.quotations.index','Quotations','admin.quotations.*',can('quotation.view')]]},{label:'Finance',links:[['invoices','admin.invoices.index','Invoices','admin.invoices.*',can('invoice.view')],['payments','admin.payments.index','Payments','admin.payments.*',can('payment.view')]]},{label:'Support',links:[['support','admin.support.index','Support Tickets','admin.support.*',can('support.view')]]}].map(group=>({...group,links:group.links.filter(link=>link[4])})).filter(group=>group.links.length));const active=link=>route().current(link[3]);
</script>
<template><div v-for="group in groups" :key="group.label" class="mb-5 last:mb-0"><p class="mb-2 px-3 text-[10px] font-bold uppercase tracking-[.16em] text-slate-400">{{ group.label }}</p><Link v-for="link in group.links" :key="link[0]" :href="route(link[1])" class="mb-1 flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm transition" :class="active(link)?'bg-[#0B3D6E] font-semibold text-white shadow-sm':'text-slate-600 hover:bg-slate-100'"><NavigationIcon :name="link[0]" :class="active(link)?'text-cyan-300':'text-slate-400'"/>{{ link[2] }}</Link></div></template>
